const CURRENCIES = new Set(['EUR', 'USD', 'GBP', 'CHF', 'CAD', 'AUD', 'JPY', 'PLN', 'AED', 'INR', 'TRY']);
const LANGUAGES = new Set(['en-gb', 'en-us', 'de', 'fr', 'es', 'it', 'nl', 'pt-pt', 'pl', 'ja', 'ko', 'zh-cn']);
const SORTS = new Set(['popularity', 'price_low', 'price_high', 'stars', 'distance', 'review_score']);
const MAX_PROPERTY_ROWS = 1000;
const MAX_DATASET_ROWS = 1001;
const PAGE_SIZE = 1000;
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/;

function fail(code) {
  throw new Error(code);
}

function upper(value) {
  return String(value ?? '').trim().toUpperCase();
}

function boundedInteger(value, code, minimum, maximum) {
  const parsed = Number(value);
  if (!Number.isInteger(parsed) || parsed < minimum || parsed > maximum) fail(code);
  return parsed;
}

function positiveFinite(value, code, minimum, maximum) {
  const parsed = Number(value);
  if (!Number.isFinite(parsed) || parsed < minimum || parsed > maximum) fail(code);
  return parsed;
}

function isoDate(value, placeholderCode, invalidCode) {
  const text = String(value ?? '').trim();
  if (!text || text.startsWith('REPLACE_WITH_')) fail(placeholderCode);
  if (!DATE_RE.test(text) || Number.isNaN(Date.parse(`${text}T00:00:00Z`))) fail(invalidCode);
  return text;
}

function preflightBookingHotelsConfig(raw = {}) {
  const destination = String(raw.destination ?? '').trim();
  if (!destination || destination === 'REPLACE_WITH_DESTINATION' || destination.length > 160) fail('DESTINATION_NOT_CONFIGURED');
  const checkIn = isoDate(raw.checkIn, 'CHECK_IN_NOT_CONFIGURED', 'INVALID_CHECK_IN_DATE');
  const checkOut = isoDate(raw.checkOut, 'CHECK_OUT_NOT_CONFIGURED', 'INVALID_CHECK_OUT_DATE');
  if (Date.parse(`${checkOut}T00:00:00Z`) <= Date.parse(`${checkIn}T00:00:00Z`)) fail('CHECK_OUT_MUST_BE_AFTER_CHECK_IN');

  const spreadsheetId = String(raw.spreadsheetId ?? '').trim();
  const sheetName = String(raw.sheetName ?? '').trim();
  if (!spreadsheetId || spreadsheetId === 'REPLACE_WITH_SPREADSHEET_ID') fail('SPREADSHEET_ID_NOT_CONFIGURED');
  if (!/^[a-zA-Z0-9-_]{20,}$/.test(spreadsheetId)) fail('INVALID_SPREADSHEET_ID');
  if (!sheetName || sheetName === 'REPLACE_WITH_SHEET_NAME' || sheetName.length > 100) fail('SHEET_NAME_NOT_CONFIGURED');

  const adults = boundedInteger(raw.adults, 'INVALID_ADULTS_1_TO_30', 1, 30);
  const rooms = boundedInteger(raw.rooms, 'INVALID_ROOMS_1_TO_30', 1, 30);
  const maxProperties = boundedInteger(raw.maxProperties, 'INVALID_MAX_PROPERTIES_1_TO_1000', 1, MAX_PROPERTY_ROWS);
  const maxPagesPerTarget = boundedInteger(raw.maxPagesPerTarget, 'INVALID_MAX_PAGES_1_TO_40', 1, 40);
  const maxRequests = boundedInteger(raw.maxRequests, 'INVALID_MAX_REQUESTS_1_TO_250', 1, 250);
  const maxRuntimeSecs = boundedInteger(raw.maxRuntimeSecs, 'INVALID_MAX_RUNTIME_30_TO_3600', 30, 3600);

  const currency = upper(raw.currency || 'EUR');
  const language = String(raw.language ?? 'en-gb').trim().toLowerCase();
  const sortBy = String(raw.sortBy ?? 'popularity').trim();
  if (!CURRENCIES.has(currency)) fail('INVALID_CURRENCY');
  if (!LANGUAGES.has(language)) fail('INVALID_LANGUAGE');
  if (!SORTS.has(sortBy)) fail('INVALID_SORT_ORDER');
  const maxCostPerRunUsd = positiveFinite(raw.maxCostPerRunUsd, 'INVALID_MAX_CHARGE_CAP', 0.02139, 5);

  return {
    destination,
    checkIn,
    checkOut,
    currency,
    spreadsheetId,
    sheetName,
    targetCount: 1,
    maxProperties,
    maxCostPerRunUsd,
    actorInput: {
      destination,
      checkIn,
      checkOut,
      adults,
      rooms,
      children: 0,
      childrenAges: [],
      flexibleDays: '0',
      maxProperties,
      mode: 'fast',
      sortBy,
      currency,
      language,
      maxPagesPerTarget,
      maxRequests,
      maxRuntimeSecs,
      maxCostUsd: 0.25,
      maxBuyerChargeUsd: maxCostPerRunUsd,
      requestTimeoutSecs: 35,
      maxRetries: 1,
    },
  };
}

function classifyBookingTerminalRun(run = {}, expectedBuildId = '') {
  const status = upper(run.status);
  const runId = String(run.id ?? '');
  const runUrl = runId ? `https://console.apify.com/actors/runs/${runId}` : 'https://console.apify.com/actors/runs';
  if (run.error || !status) {
    return { ok: false, state: 'WORKFLOW_NODE_FAILED', run, runId, runUrl, reason: 'APIFY_RUN_NODE_ERROR' };
  }
  if (status !== 'SUCCEEDED') {
    return { ok: false, state: 'ACTOR_FAILED_OR_ABORTED', run, runId, runUrl, reason: `ACTOR_STATUS_${status}` };
  }
  if (!expectedBuildId || String(run.buildId ?? '') !== String(expectedBuildId)) {
    return { ok: false, state: 'WORKFLOW_NODE_FAILED', run, runId, runUrl, reason: 'RUN_BUILD_ID_MISMATCH' };
  }
  if (!run.defaultKeyValueStoreId || !run.defaultDatasetId) {
    return { ok: false, state: 'WORKFLOW_NODE_FAILED', run, runId, runUrl, reason: 'RUN_STORAGE_IDS_MISSING' };
  }
  return { ok: true, state: 'RUN_SUCCEEDED', run, runId, runUrl };
}

function exactBookingBuyerCharge(billing) {
  if (billing?.billingMode !== 'pay_per_event') fail('PPE_PRICING_NOT_ACTIVE');
  const prices = billing.effectiveEventPricesUsd;
  const counts = billing.counts;
  if (!prices || typeof prices !== 'object' || !counts || typeof counts !== 'object') {
    fail('AUTHORITATIVE_PPE_ACCOUNTING_MISSING');
  }
  const chargedCounts = {};
  let total = 0;
  for (const [eventName, eventCounts] of Object.entries(counts)) {
    const charged = Number(eventCounts?.charged ?? 0);
    if (!Number.isInteger(charged) || charged < 0) fail('INVALID_CHARGED_EVENT_COUNT');
    chargedCounts[eventName] = charged;
    if (charged === 0) continue;
    const price = Number(prices[eventName]);
    if (!Number.isFinite(price) || price < 0) fail('INVALID_EFFECTIVE_EVENT_PRICE');
    total += charged * price;
  }
  return {
    actualBuyerChargeUsd: Number(total.toFixed(12)),
    chargedCounts,
    effectivePricesUsd: { ...prices },
  };
}

function parseBookingOutputRecord(record = {}, run = {}) {
  const runId = String(run.id ?? '');
  const runUrl = runId ? `https://console.apify.com/actors/runs/${runId}` : 'https://console.apify.com/actors/runs';
  const identity = { run, runId, runUrl };
  const recordIsObject = record && typeof record === 'object' && !Array.isArray(record);
  const data = recordIsObject && !record.error
    ? (Object.prototype.hasOwnProperty.call(record, 'data') ? record.data : record)
    : null;
  if (!data || typeof data !== 'object' || Array.isArray(data) || data.error) {
    return { ok: false, state: 'WORKFLOW_NODE_FAILED', ...identity, reason: 'OUTPUT_SUMMARY_MISSING_OR_INVALID' };
  }
  let ppe;
  try { ppe = exactBookingBuyerCharge(data.billing); } catch (error) {
    return { ok: false, state: 'WORKFLOW_NODE_FAILED', ...identity, reason: error.message };
  }
  const outputRows = Number(data.propertyRows);
  const targetCount = Number(data.targetCount);
  if (!Number.isInteger(outputRows) || outputRows < 0 || outputRows > MAX_PROPERTY_ROWS) {
    return { ok: false, state: 'WORKFLOW_NODE_FAILED', ...identity, reason: 'OUTPUT_PROPERTY_ROW_COUNT_INVALID' };
  }
  const zeroCapacityGuard = targetCount === 0
    && outputRows === 0
    && upper(data.coverageState) === 'CAPPED'
    && upper(data.coverageStatus) === 'CAPPED'
    && data.stoppedByBillingGuard === true
    && Array.isArray(data.perTarget)
    && data.perTarget.length === 0;
  if (!Number.isInteger(targetCount) || targetCount < 0 || !Array.isArray(data.perTarget)
    || data.perTarget.length !== targetCount || (targetCount === 0 && !zeroCapacityGuard)) {
    return { ok: false, state: 'WORKFLOW_NODE_FAILED', ...identity, reason: 'OUTPUT_TARGET_CONTRACT_MISSING' };
  }
  if (Number(ppe.chargedCounts.fast_property_result ?? 0) !== outputRows) {
    return { ok: false, state: 'WORKFLOW_NODE_FAILED', ...identity, reason: 'PPE_PROPERTY_DELIVERY_COUNT_MISMATCH' };
  }
  return {
    ok: true,
    state: 'SUMMARY_READY',
    ...identity,
    buyerChargeUsd: ppe.actualBuyerChargeUsd,
    summary: {
      schemaVersion: 2,
      sourceRecordKey: 'OUTPUT',
      status: upper(data.status),
      coverageState: upper(data.coverageState),
      coverageStatus: upper(data.coverageStatus),
      outputRows,
      expectedDatasetRows: outputRows + 1,
      targetCount,
      perTarget: data.perTarget,
      warnings: Array.isArray(data.warnings) ? data.warnings.map(String) : [],
      ppe: {
        ...ppe,
        deliveryEventLimitReached: data.billing?.eventLimitReached === true || data.stoppedByBillingGuard === true,
      },
    },
  };
}

function planBookingDatasetPages(summary, pageSize = PAGE_SIZE) {
  const total = boundedInteger(summary?.expectedDatasetRows, 'INVALID_SUMMARY_DATASET_ROWS', 1, MAX_DATASET_ROWS);
  const size = boundedInteger(pageSize, 'INVALID_DATASET_PAGE_SIZE', 1, PAGE_SIZE);
  return Array.from({ length: Math.ceil(total / size) }, (_, index) => ({
    offset: index * size,
    limit: Math.min(size, total - (index * size)),
    expectedRows: total,
  }));
}

function normalizedBookingPropertyPath(canonicalUrl) {
  try {
    const url = new URL(String(canonicalUrl ?? '').trim());
    if (!/(^|\.)booking\.com$/i.test(url.hostname) || !/^\/hotel\//i.test(url.pathname)) return null;
    return url.pathname.toLowerCase()
      .replace(/\/{2,}/g, '/')
      .replace(/\.[a-z]{2}(?:-[a-z]{2})?\.html$/i, '.html');
  } catch {
    return null;
  }
}

function bookingStableIdentity({ stablePropertyKey, canonicalUrl, propertyId }) {
  const canonicalPath = normalizedBookingPropertyPath(canonicalUrl);
  if (canonicalPath) return `booking_path:${canonicalPath}`;
  const actorStableKey = String(stablePropertyKey ?? '').trim();
  if (actorStableKey) return actorStableKey;
  const id = String(propertyId ?? '').trim();
  if (!id) fail('PROPERTY_ID_REQUIRED_FOR_STABLE_UPSERT');
  return id;
}

function bookingUpsertKey({ stablePropertyKey, canonicalUrl, propertyId, checkIn, checkOut, currency }) {
  const identity = bookingStableIdentity({ stablePropertyKey, canonicalUrl, propertyId });
  if (!DATE_RE.test(String(checkIn ?? '')) || !DATE_RE.test(String(checkOut ?? ''))) fail('DATES_REQUIRED_FOR_STABLE_UPSERT');
  const normalizedCurrency = upper(currency);
  if (!CURRENCIES.has(normalizedCurrency)) fail('CURRENCY_REQUIRED_FOR_STABLE_UPSERT');
  return `${identity}|${checkIn}|${checkOut}|${normalizedCurrency}`;
}

function scalar(value) {
  if (value === null || value === undefined) return '';
  if (typeof value === 'string' || typeof value === 'number' || typeof value === 'boolean') return value;
  return JSON.stringify(value);
}

function prepareSheetRow(row, config, context) {
  const search = row.searchParameters;
  if (!search || typeof search !== 'object'
    || String(search.checkIn ?? '') !== config.checkIn
    || String(search.checkOut ?? '') !== config.checkOut
    || upper(search.currency) !== config.currency) {
    fail('PROPERTY_SEARCH_CONTEXT_MISMATCH');
  }
  const upsertKey = bookingUpsertKey({
    stablePropertyKey: row.stablePropertyKey,
    canonicalUrl: row.canonicalUrl,
    propertyId: row.propertyId,
    checkIn: config.checkIn,
    checkOut: config.checkOut,
    currency: config.currency,
  });
  return {
    upsertKey,
    stablePropertyKey: scalar(row.stablePropertyKey || bookingStableIdentity(row)),
    propertyId: scalar(row.propertyId),
    name: scalar(row.name),
    checkIn: config.checkIn,
    checkOut: config.checkOut,
    requestedCurrency: config.currency,
    resultCurrency: scalar(row.priceCurrency),
    stayTotalAmount: scalar(row.stayTotalAmount),
    stayNights: scalar(row.stayNights),
    nightlyAmount: scalar(row.nightlyAmount),
    guestReviewScore: scalar(row.guestReviewScore),
    guestReviewCount: scalar(row.guestReviewCount),
    stars: scalar(row.stars),
    availabilityStatus: scalar(row.availabilityStatus),
    locationText: scalar(row.locationText),
    canonicalUrl: scalar(row.canonicalUrl),
    priceBasis: scalar(row.priceBasis),
    checkoutVerified: scalar(row.checkoutVerified),
    collectedAt: scalar(row.collectedAt),
    coverageState: context.coverageState,
    workflowState: context.workflowState,
    exactActorChargeUsd: context.buyerChargeUsd,
    actorRunId: context.runId,
  };
}

function reconcileBookingHotelsRun({ run = {}, summary = {}, rows = [], config = {} }) {
  const runId = String(run.id ?? '');
  const runUrl = runId ? `https://console.apify.com/actors/runs/${runId}` : 'https://console.apify.com/actors/runs';
  const datasetUrl = run.defaultDatasetId
    ? `https://console.apify.com/storage/datasets/${run.defaultDatasetId}`
    : runUrl;
  const buyerChargeUsd = Number(summary?.ppe?.actualBuyerChargeUsd);
  const base = {
    run, summary, runId, runUrl, datasetUrl, buyerChargeUsd,
    baselineState: 'NOT_APPLICABLE_STATELESS_SNAPSHOT',
    unchangedState: 'NOT_CLAIMED_GOOGLE_SHEETS_UPSERT_ONLY',
  };
  if (!Number.isFinite(buyerChargeUsd) || buyerChargeUsd < 0) {
    return { ...base, state: 'WORKFLOW_NODE_FAILED', reason: 'AUTHORITATIVE_BUYER_CHARGE_MISSING', shouldWrite: false, sheetRows: [] };
  }
  const zeroCapacityGuard = Number(summary.targetCount) === 0
    && Number(summary.outputRows) === 0
    && upper(summary.coverageState) === 'CAPPED'
    && summary.ppe?.deliveryEventLimitReached === true;
  if (!zeroCapacityGuard && Number(summary.targetCount) !== Number(config.targetCount)) {
    return { ...base, state: 'WORKFLOW_NODE_FAILED', reason: 'TARGET_RECONCILIATION_MISMATCH', shouldWrite: false, sheetRows: [] };
  }
  if (rows.some((row) => row?.error)) {
    return { ...base, state: 'WORKFLOW_NODE_FAILED', reason: 'DATASET_READ_ERROR', shouldWrite: false, sheetRows: [] };
  }
  const normalized = rows.filter((row) => row && typeof row === 'object' && Object.keys(row).length && !row.error);
  const properties = normalized.filter((row) => row.recordType === 'property');
  const coverageRows = normalized.filter((row) => row.recordType === 'coverage');
  if (coverageRows.length !== 1 || normalized.length !== Number(summary.expectedDatasetRows)) {
    return { ...base, state: 'WORKFLOW_NODE_FAILED', reason: 'DATASET_OR_COVERAGE_COUNT_MISMATCH', shouldWrite: false, sheetRows: [] };
  }
  if (properties.length !== Number(summary.outputRows)) {
    return { ...base, state: 'WORKFLOW_NODE_FAILED', reason: 'PROPERTY_ROW_COUNT_MISMATCH', shouldWrite: false, sheetRows: [] };
  }

  const coverageRecord = coverageRows[0];
  if (Number(coverageRecord.targetCount) !== Number(summary.targetCount)
    || upper(coverageRecord.coverageState) !== upper(summary.coverageState)
    || upper(coverageRecord.coverageStatus) !== upper(summary.coverageStatus)) {
    return { ...base, state: 'WORKFLOW_NODE_FAILED', reason: 'OUTPUT_DATASET_COVERAGE_MISMATCH', shouldWrite: false, sheetRows: [] };
  }

  if (zeroCapacityGuard) {
    return {
      ...base,
      state: 'CAPPED',
      reason: 'PPE_ALLOWANCE_ZERO_SOURCE_NOT_STARTED',
      coverageState: 'CAPPED',
      shouldWrite: false,
      sheetRows: [],
    };
  }

  const coverageState = upper(summary.coverageState || coverageRecord.coverageState);
  const status = upper(summary.status || summary.coverageStatus);
  if (['FAILED', 'BLOCKED'].includes(coverageState) || status === 'FAILED') {
    return { ...base, state: 'FAILED', reason: 'SOURCE_FAILED_OR_BLOCKED', coverageState, shouldWrite: false, sheetRows: [] };
  }
  if (coverageState === 'PARTIAL' || status === 'PARTIAL') {
    return { ...base, state: 'PARTIAL', reason: 'SOURCE_COVERAGE_PARTIAL', coverageState, shouldWrite: false, sheetRows: [] };
  }
  const workflowState = coverageState === 'CAPPED' || summary.ppe?.deliveryEventLimitReached === true
    ? 'CAPPED'
    : 'READY_TO_WRITE';

  const seen = new Set();
  const sheetRows = [];
  try {
    for (const property of properties) {
      const row = prepareSheetRow(property, config, { coverageState, workflowState, buyerChargeUsd, runId });
      if (seen.has(row.upsertKey)) continue;
      seen.add(row.upsertKey);
      sheetRows.push(row);
    }
  } catch (error) {
    return { ...base, state: 'WORKFLOW_NODE_FAILED', reason: error.message, coverageState, shouldWrite: false, sheetRows: [] };
  }
  if (sheetRows.length !== properties.length) {
    return { ...base, state: 'WORKFLOW_NODE_FAILED', reason: 'DUPLICATE_UPSERT_KEYS_IN_DATASET', coverageState, shouldWrite: false, sheetRows: [] };
  }
  const allEmpty = coverageState === 'EMPTY_CONFIRMED';
  if (!sheetRows.length && allEmpty) {
    return { ...base, state: 'EMPTY_VERIFIED', reason: 'SOURCE_VERIFIED_EMPTY', coverageState, shouldWrite: false, sheetRows: [] };
  }
  if (!sheetRows.length) {
    return { ...base, state: 'WORKFLOW_NODE_FAILED', reason: 'ZERO_ROWS_WITHOUT_VERIFIED_EMPTY', coverageState, shouldWrite: false, sheetRows: [] };
  }
  return {
    ...base,
    state: workflowState,
    reason: workflowState === 'CAPPED' ? 'BOUNDED_SHORTLIST_WRITTEN_WITH_CAP_DISCLOSED' : 'VERIFIED_SHORTLIST_READY',
    coverageState,
    shouldWrite: true,
    sheetRows,
  };
}

function renderBookingReceipt(result = {}, writtenRows = null) {
  const labels = {
    READY_TO_WRITE: 'Booking.com shortlist verified',
    CAPPED: 'Booking.com bounded shortlist verified',
    EMPTY_VERIFIED: 'Booking.com search verified empty',
    PARTIAL: 'Booking.com search partial — no Sheet write',
    FAILED: 'Booking.com source failed — no Sheet write',
    ACTOR_FAILED_OR_ABORTED: 'Booking Hotels Actor failed or stopped',
    WORKFLOW_NODE_FAILED: 'Workflow could not verify Booking.com output',
  };
  return {
    state: result.state,
    label: labels[result.state] ?? 'Booking.com shortlist result',
    reason: result.reason ?? null,
    rowsPrepared: Array.isArray(result.sheetRows) ? result.sheetRows.length : 0,
    rowsWritten: Number.isInteger(writtenRows) ? writtenRows : null,
    exactActorChargeUsd: Number.isFinite(Number(result.buyerChargeUsd)) ? Number(result.buyerChargeUsd) : null,
    coverageState: result.coverageState ?? null,
    baselineState: result.baselineState ?? 'NOT_APPLICABLE_STATELESS_SNAPSHOT',
    unchangedState: result.unchangedState ?? 'NOT_CLAIMED_GOOGLE_SHEETS_UPSERT_ONLY',
    runId: result.runId ?? null,
    runUrl: result.runUrl ?? 'https://console.apify.com/actors/runs',
    datasetUrl: result.datasetUrl ?? result.runUrl ?? 'https://console.apify.com/actors/runs',
  };
}

const BOOKING_HOTELS_WORKFLOW_LIMITS = Object.freeze({ maxPropertyRows: MAX_PROPERTY_ROWS, maxDatasetRows: MAX_DATASET_ROWS, pageSize: PAGE_SIZE });


return [{ json: preflightBookingHotelsConfig($input.first().json) }];

